Ensure they work correctly in isolation and combination.

---

## 6. Advanced Patterns

### a. Stacking Decorators

Decorators are applied bottom-up:

```python
@decorator1
@decorator2
def func():
    pass
# Equivalent to: func = decorator1(decorator2(func))
```

### b. Decorator with State (Class-Based)

```python
class RateLimiter:
    def __init__(self, max_calls, period):
        self.max_calls = max_calls
        self.period = period
        self.calls = []

    def __call__(self, func):
        from functools import wraps
        import time
        @wraps(func)
        def wrapper(*args, **kwargs):
            now = time.time()
            self.calls = [t for t in self.calls if now - t < self.period]
            if len(self.calls) >= self.max_calls:
                raise Exception("Rate limit exceeded")
            self.calls.append(now)
            return func(*args, **kwargs)
        return wrapper

@RateLimiter(max_calls=5, period=10)
def api_call():
    print("API called")
```

### c. Optional Decorator Arguments

```python
def optional_decorator(_func=None, *, prefix=""):
    def decorator(func):
        from functools import wraps
        @wraps(func)
        def wrapper(*args, **kwargs):
            print(f"{prefix}Calling {func.__name__}")
            return func(*args, **kwargs)
        return wrapper

    if _func:
        return decorator(_func)
    return decorator

@optional_decorator
def func1():
    pass

@optional_decorator(prefix="[LOG]")
def func2():
    pass
```

